local CameraScript = {
    -- Editor-exposed properties
    properties = {
    }
}

local camera_x = 0.0
local is_Cursor_locked = false

local last_mouse_y = 0.0

function CameraScript:init()
    -- 'self.scene' and 'self.entity' are provided by the engine
    RegisterEngineEvent(self, "onUpdate")
end

        
function CameraScript:onUpdate()
    local obj = Object(self.scene, self.entity)
    
    local mousePos = Input.getMousePosition()
    
    if Input.isKeyPressed(Input.KEY_ESCAPE) then
            if is_Cursor_locked == true then
                    is_Cursor_locked = false
            end
    end  
    if Input.isMousePressed(Input.MOUSE_BUTTON_MIDDLE) then
            if is_Cursor_locked == false then
                    is_Cursor_locked = true
                    
                    last_mouse_y = mousePos.y
            end
    end
    
    if is_Cursor_locked == true then
            local delta_y = mousePos.y - last_mouse_y
            
            camera_x = camera_x + (delta_y * 0.05)
            
            if camera_x > 80.0 then
            camera_x = 80.0
            elseif camera_x < -80.0 then
            camera_x = -80.0
            end
            
            obj.rotation = Quaternion(-camera_x, 0.0, 0.0)
   end
   
   last_mouse_y = mousePos.y
end

return CameraScript
